  function buildTagSubmenu(label, tags, text, idPrefix) {
    var items = [];
    for (var i = 0; i < tags.length; i++) {
      var tagName = '#' + tags[i];
      var active = hasTag(text, tagName);
      items.push({
        id: idPrefix + tags[i],
        label: (active ? '\u2713 ' : '') + tagName
      });
    }
    return { id: idPrefix + '_sub', label: label, items: items };
  }

