        deliveries: 'badge', version: 'badge',
        priority: 'header', moscow: 'header',
        'status-review': 'footer', 'time-estimate': 'badge',
        'status-testing': 'footer',
        positivity: 'badge', 'teaching-platform': 'badge',
        'product-platform': 'badge',
