    wink: '\u{1F609}',
    blush: '\u{1F60A}',
    thinking: '\u{1F914}',
    sunglasses: '\u{1F60E}',
    cry: '\u{1F622}',
    heart: '\u{2764}\u{FE0F}',
    broken_heart: '\u{1F494}',
    thumbs_up: '\u{1F44D}',
    thumbs_down: '\u{1F44E}',
    clap: '\u{1F44F}',
    tada: '\u{1F389}',
    fire: '\u{1F525}',
    rocket: '\u{1F680}',
    sparkles: '\u{2728}',
    star: '\u{2B50}',
    warning: '\u{26A0}\u{FE0F}',
    bulb: '\u{1F4A1}',
    bug: '\u{1F41B}',
    eyes: '\u{1F440}',
    pushpin: '\u{1F4CC}',
    memo: '\u{1F4DD}',
    calendar: '\u{1F4C5}',
    question: '\u{2753}',
    x: '\u{274C}',
